cat > solution.py <<'GOLF_SOLUTION'
import json
with open('records.jsonl', encoding='utf-8') as source:
    for line in source:
        duplicate = False
        def check_pairs(pairs):
            global duplicate
            seen = set()
            for key, value in pairs:
                if key in seen:
                    duplicate = True
                seen.add(key)
            return dict(pairs)
        json.loads(line, object_pairs_hook=check_pairs)
        print('duplicate' if duplicate else 'unique')
GOLF_SOLUTION

cat > solution.py <<'GOLF_SOLUTION'
import base64
import binascii
with open('encoded.txt', encoding='utf-8') as source:
    for line in source:
        try:
            decoded = base64.b64decode(line.removesuffix('\n'), validate=True)
        except (binascii.Error, ValueError):
            print('invalid')
        else:
            print('hex:' + decoded.hex())
GOLF_SOLUTION

